const h = params.height;
const R = h * 0.82;
const rimR = R * 0.19;
const rockMat = { preset: 'stone', roughness: 1, flatShading: true };
const darkRock = '#292623';
const warmRock = '#514138';
const ashRock = '#71665c';
const profile = [
  [0, h * 0.70],
  [rimR * 0.45, h * 0.71],
  [rimR * 0.82, h * 0.88],
  [rimR, h],
  [R * 0.28, h * 0.83],
  [R * 0.48, h * 0.61],
  [R * 0.70, h * 0.34],
  [R * 0.90, h * 0.10],
  [R, 0],
  [0, 0]
];
const mountain = api.lathe(profile, 48);
mountain.displace((x, y, z) => {
  const radial = Math.sqrt(x * x + z * z) / R;
  const coarse = api.fbm2(x * 0.075 + y * 0.035, z * 0.075 - y * 0.025, 4);
  const ridges = Math.abs(api.noise2(Math.atan2(z, x) * 3.2, y * 0.12)) - 0.45;
  return h * (0.018 + radial * 0.025) * coarse + h * 0.012 * ridges;
});
mountain.vertexColor((x, y, z) => {
  const n = api.fbm2(x * 0.11 + y * 0.04, z * 0.11, 3);
  const high = Math.max(0, Math.min(1, y / h));
  const base = api.mix(darkRock, warmRock, 0.38 + n * 0.22);
  return api.mix(base, ashRock, high * 0.32);
});
api.add(mountain, rockMat);
const lavaMat = { preset: 'lava', color: params.lavaColor, emissive: params.lavaColor, emissiveIntensity: 4.5, roughness: 0.22 };
const hotMat = { preset: 'emissive', color: '#ffd36a', emissive: params.lavaColor, emissiveIntensity: 7, roughness: 0.15 };
const pool = api.cylinder(rimR * 0.63, rimR * 0.63, h * 0.018, 32).translate(0, h * 0.715, 0);
pool.vertexColor((x, y, z) => api.mix(params.lavaColor, '#ffd76a', 0.25 + 0.35 * api.noise2(x * 0.7, z * 0.7)));
api.add(pool, lavaMat);
api.add(api.torus(rimR * 0.52, h * 0.018).rotate(90, 0, 0).translate(0, h * 0.73, 0), hotMat);
const flowCount = 8;
for (let i = 0; i < flowCount; i++) {
  const baseA = i * Math.PI * 2 / flowCount + (api.rng() - 0.5) * 0.28;
  const reach = R * (0.72 + api.rng() * 0.25);
  const points = [];
  const steps = 9;
  for (let j = 0; j < steps; j++) {
    const t = j / (steps - 1);
    const r = rimR * 0.64 + (reach - rimR * 0.64) * t;
    const bend = Math.sin(t * Math.PI * (1.3 + i * 0.07) + i) * 0.10 + (api.noise2(i * 2.7, t * 4.5) * 0.07);
    const a = baseA + bend;
    const q = r / R;
    let y = h * (1 - Math.pow(q, 0.72)) * 0.96;
    if (j === 0) y = h * 0.75;
    y += h * 0.016;
    points.push([Math.cos(a) * r, y, Math.sin(a) * r]);
  }
  const flow = api.tube(points, h * (0.020 + api.rng() * 0.008), 7);
  api.add(flow, lavaMat);
  if (i % 2 === 0) {
    const split = [];
    for (let j = 4; j < steps; j++) {
      const t = j / (steps - 1);
      const r = rimR * 0.64 + (reach - rimR * 0.64) * t;
      const a = baseA + 0.12 + (t - 0.45) * (0.18 + 0.04 * i);
      const q = r / R;
      const y = h * (1 - Math.pow(q, 0.72)) * 0.96 + h * 0.018;
      split.push([Math.cos(a) * r, y, Math.sin(a) * r]);
    }
    api.add(api.tube(split, h * 0.014, 6), lavaMat);
  }
}
for (let i = 0; i < 18; i++) {
  const a = i * Math.PI * 2 / 18 + (api.rng() - 0.5) * 0.13;
  const rr = rimR * (0.88 + api.rng() * 0.22);
  const size = h * (0.025 + api.rng() * 0.025);
  const rock = api.icosphereRock(size, 0.65).scale(1.3, 0.8 + api.rng() * 0.5, 1).translate(Math.cos(a) * rr, h * (0.91 + api.rng() * 0.07), Math.sin(a) * rr);
  rock.vertexColor(() => api.mix(darkRock, ashRock, api.rng() * 0.45));
  api.add(rock, rockMat);
}
api.collider({ kind: 'cylinder', radius: R, halfHeight: h * 0.10, offset: [0, h * 0.10, 0] });
api.collider({ kind: 'cylinder', radius: R * 0.72, halfHeight: h * 0.20, offset: [0, h * 0.28, 0] });
api.collider({ kind: 'cylinder', radius: R * 0.47, halfHeight: h * 0.22, offset: [0, h * 0.56, 0] });
api.collider({ kind: 'cylinder', radius: R * 0.25, halfHeight: h * 0.13, offset: [0, h * 0.82, 0] });
return api.build();
